def islands_after_additions(rows, cols, positions):
    parent = {}
    rank = {}
    count = 0
    result = []

    def find(x):
        while parent[x] != x:
            parent[x] = parent[parent[x]]
            x = parent[x]
        return x

    def union(a, b):
        ra, rb = find(a), find(b)
        if ra == rb:
            return False
        if rank[ra] < rank[rb]:
            ra, rb = rb, ra
        parent[rb] = ra
        if rank[ra] == rank[rb]:
            rank[ra] += 1
        return True

    for r, c in positions:
        idx = r * cols + c
        if idx in parent:
            result.append(count)
            continue
        parent[idx] = idx
        rank[idx] = 0
        count += 1
        for dr, dc in ((1, 0), (-1, 0), (0, 1), (0, -1)):
            nr, nc = r + dr, c + dc
            if 0 <= nr < rows and 0 <= nc < cols:
                nidx = nr * cols + nc
                if nidx in parent and union(idx, nidx):
                    count -= 1
        result.append(count)
    return result
